require dirname(__DIR__).'/config.php';require_once dirname(__DIR__).'/mgs-integration-lib.php';require_once dirname(__DIR__).'/inventory-operations-lib.php';
$db=app_db();$run=date('YmdHis').random_int(10,99);$itemId=0;$docIds=[];$docNos=[];$errors=[];$warehouse=['id'=>1,'role'=>'employee','employee_role'=>'warehouse','full_name'=>'Warehouse Smoke'];$manager=['id'=>2,'role'=>'employee','account_type'=>'admin','employee_role'=>'admin','full_name'=>'Admin Approver Smoke'];
try{app_inventory_ensure_operational_schema($db);$s=$db->prepare('INSERT INTO inventory_stock_items(sku,item_name,category,unit,quantity_on_hand,minimum_quantity,status)VALUES(:sku,:name,"other","eded",0,0,"active")');$s->execute(['sku'=>'RET-'.$run,'name'=>'Return Smoke '.$run]);$itemId=(int)$db->lastInsertId();app_inventory_post_intake($db,['item_id'=>$itemId,'quantity'=>8,'to_location_type'=>'branch','to_location_id'=>'1'],$warehouse);
$invalid=app_inventory_create_external_request($db,['source_location_type'=>'branch','source_location_id'=>'','destination_type'=>'company','destination_name'=>'Bad request','items'=>[['item_id'=>0,'quantity'=>0]]],$warehouse);if(($invalid['error']??'')!=='invalid_request')$errors[]='invalid_request_accepted';
