app_inventory_post_intake($db,['item_id'=>$itemId,'quantity'=>2,'to_location_type'=>'warehouse','to_location_id'=>'MAIN'],$warehouse);$warehouseReq=app_inventory_create_external_request($db,['source_location_type'=>'warehouse','source_location_id'=>'MAIN','destination_type'=>'company','destination_name'=>'Warehouse Supplier '.$run,'reason'=>'wrong_delivery','disposition'=>'return_to_supplier','items'=>[['item_id'=>$itemId,'quantity'=>1]]],$warehouse);$docIds[]=(int)($warehouseReq['id']??0);$docNos[]=(string)($warehouseReq['document_no']??'');$warehouseOk=app_inventory_approve_request($db,(int)$warehouseReq['id'],$manager);if(empty($warehouseOk['ok'])||app_inventory_company_quantity($db,$itemId)!==6.0||app_inventory_location_quantity($db,$itemId,'warehouse','MAIN')!==1.0)$errors[]='warehouse_return_failed';
