}finally{foreach($docNos as $no){if($no!=='')$db->prepare('DELETE FROM mgs_operation_actions WHERE entity_id=:no')->execute(['no'=>$no]);}foreach($docIds as $id){if($id){$db->prepare('DELETE FROM inventory_document_items WHERE document_id=:id')->execute(['id'=>$id]);$db->prepare('DELETE FROM inventory_documents WHERE id=:id')->execute(['id'=>$id]);}}if($itemId){$db->prepare('DELETE FROM inventory_document_items WHERE item_id=:id')->execute(['id'=>$itemId]);$db->prepare('DELETE FROM inventory_documents WHERE entity_item_id=:id')->execute(['id'=>$itemId]);$db->prepare('DELETE FROM inventory_location_balances WHERE item_id=:id')->execute(['id'=>$itemId]);$db->prepare('DELETE FROM inventory_lifecycle_movements WHERE product_id=:id')->execute(['id'=>$itemId]);$db->prepare('DELETE FROM inventory_stock_movements WHERE item_id=:id')->execute(['id'=>$itemId]);$db->prepare('DELETE FROM inventory_stock_items WHERE id=:id')->execute(['id'=>$itemId]);}}
